        "L":0,
        "G":0,
        "C":0,
        "I":0,
        "Output":"**Clearing**\nThe tower is in the middle of a grass clearing, surrounded on all sides by a forest. The forest is beautiful. It looks like it was pulled straight from a fantasy story, with the way the light filters through the trees, the butterflies flying in every direction you look, and the multicolored flowers covering part of the forest's floor.\nYou can see two paths leading away from the clearing, on opposite sides of the tower. The one to the right of the tower's entrance is where you can see the colorful flowers. To the left, you can see the path slope upward to climb a hill. You also see some sort of house off to the side.\nYou can take the flower path, the hill path, approach the house, or go into the tower."
