        "Pq":0,
        "Command":"look",
        "Input":"-",
        "L":0,
        "G":0,
        "C":0,
        "I":0,
        "Output":"**Frost Field**\nMost other areas in the forest are pleasantly warm, but this field is cold. What appears at first to be a large sheet of ice is actually many individual flowers. The petals of the flowers are ice crystals with a light blue color, and they sparkle in the daylight. The river is on the left side of the field, and the flowers go right up to the bank.\nYou can go back to the campsite."
