        "L":0,
        "G":0,
        "C":27,
        "I":0,
        "Output":"I think it's about time we finally talk for real. Hello, my name is Positron, and I am everything that you can see, and everything that you can do. My name, if you're curious, is a pun of the word \"position\", and the suffix -tron, which often implies a machine. This makes sense since I am a discord bot that allows you to explore a map.\n\nWe're going to play a game. You see these statues? This is a shrine to the Xylons' nine gods, and it has been overtaken by the darkness. Each god is associated with a color, and these statues used to have those same colors. So sad that they've all been infected by the darkness and turned black. It *is* my fault of course, but it's still sad.\n\nHere's the game: If you are the first player to guess the original colors of all nine statues, you get one crystal. But if you guess incorrectly, I will kill you.\n\nIn order from left to right, the statues depict a Rabbit, Wolf, Leopard, Fox, Parrot, Phoenix, Mouse, Raccoon, and a Snake.\nI'll even tell you the colors in a random order: Blue, Red, Pink, White, Violet, Green, Silver, Gold, and Black.\n\nTo play my game, use the command \"!guess\", followed by a list of colors separated by commas, with no spaces. The colors should be in the same order I listed the animals, from left to right. For example: \"!guess blue,red,pink,white,violet,green,silver,gold,black\", would mean you think the rabbit is blue, the wolf is red, etc. I encourage you to try using that example guess, because then I would get to kill you.\n\nYou might want to make a copy of this message, or remember where it is, because I will not be repeating myself."
